import{r as e}from"./rolldown-runtime-QTnfLwEv.js";import{_ as t,a as n,f as r,r as i,t as a}from"./vendor-react-kiGFOSem.js";import{P as o}from"./app-shared-DVJ00oqv.js";import{Ha as s,rr as c}from"./vendor-icons-DYJAWP-W.js";import{S as l}from"./index-QHcB3PPg.js";import{a as u,c as d,i as f,n as p,r as m,t as h}from"./ResourceShell-s9BnKAdj.js";var g=e(t(),1),_=[{slug:`offboard-employee-google-workspace`,title:`How to offboard an employee from Google Workspace`,description:`Suspend, sign out, revoke app access, hand over Drive, Calendar and mail, then archive or delete. Every step checked against Google's admin help.`,keyword:`how to offboard an employee from Google Workspace`,checked:`2026-10-21`,readMinutes:6,answer:`Reset the password and sign-in cookies, revoke app passwords and connected apps, then suspend the account so nothing new gets in. Transfer their Drive files and Calendar, and redirect their mail to a manager. Then archive the account (keeps the data and lets you reuse the paid seat) or delete it. Google lets you restore a deleted user for 20 days, so transfer data before you delete.`,sections:[{heading:`Suspend, archive or delete: pick the end state first`,paragraphs:[`Google gives you three states for a person who left. They differ in what they cost and what they keep.`],bullets:[`Suspend: blocks access to Gmail, Drive and other services, keeps all data, and can be undone at any time. Suspended accounts are still charged at the same rate as active ones.`,`Archive: the person cannot sign in anywhere, their data is kept, and their Workspace license becomes available to reassign within 24 hours. Business and Enterprise editions usually need an Archived User subscription (Flexible Plan customers can archive without one); archived data counts toward your pooled storage.`,`Delete: the person loses access to all services and data. Data you did not transfer is removed. You can restore the account for 20 days, after that it is gone.`],sources:[`g-suspend`,`g-archive`,`g-delete`],caution:`Google's own advice: do not delete just to block access (suspend instead) or just to save a license (archive instead).`},{heading:`Cut access on the last day`,steps:[{title:`Reset the password and the sign-in cookies`,body:[`In the Admin console go to Directory, then Users, and open the person's account page. Under Security, reset the password.`,`Then open Security, Sign-in cookies, and click Reset. This signs them out of browsers and mobile devices. It does not sign them out of apps such as Gmail and Google Drive for desktop, which is one more reason to suspend.`],sources:[`g-signout`,`g-security`]},{title:`Revoke app passwords and connected apps`,body:[`On the same Security page, open Application-specific passwords and revoke each one. Older mail clients and scripts use these to sign in without the normal password.`,`Then open Connected applications. It lists the third-party apps that can reach the person's data. Click Remove on each. Google notes that removing access does not stop the person from using the app later, so do this together with the suspension.`],sources:[`g-security`]},{title:`Wipe work data from managed phones`,body:[`If you manage their phone, open their account page, click Managed devices, and choose Wipe Account. That removes the work account and leaves personal data. Wipe Device resets the whole phone and is meant for lost or stolen devices.`,`An account wipe only works on devices under basic or advanced mobile management. Google says the user must still be able to reach their work account, so do this before you suspend, or restore the account briefly first.`],sources:[`g-wipe`]},{title:`Remove admin roles and group memberships`,body:[`Remove any admin role first. Google will not delete a user who still holds one.`,`In Directory, Groups, open each group, click Members, point to the person and click Remove. They stop getting group mail; the account itself stays until you deal with it.`],sources:[`g-delete`,`g-groups`]},{title:`Suspend the account`,body:[`In Directory, Users, point to the person and suspend them. Suspension blocks new mail and calendar invitations, keeps every file, and resets their sign-in cookies automatically.`],sources:[`g-suspend`,`g-signout`]}]},{heading:`Hand over Drive, Calendar and email`,steps:[{title:`Transfer Drive files to a manager`,body:[`In the Admin console go to Apps, Google Workspace, Drive and Docs, then Transfer ownership. Pick the From and To users and click Transfer Files. You need the Drive and Docs administrator privilege.`,`Before you start: move anything out of Trash (Trash is not transferred) and move unorganized files into their My Drive. The new owner must be active and have enough storage. Transfers that run longer than 36 hours fail and must be restarted.`,`The files land in a transfer folder in the new owner's My Drive. Files in shared drives already belong to the organization and are not deleted with the user.`],sources:[`g-drive`,`g-delete`]},{title:`Transfer Calendar data when you delete`,body:[`Super admins can transfer Drive files and primary Calendar data in the same delete dialog: next to Data in other apps, choose Transfer, pick the recipient (for example, the manager), and tick the data types.`],sources:[`g-delete`]},{title:`Route their email to a manager`,body:[`Google lists two ways to keep a leaver's mail: migrate it to another account, or redirect new messages to another address.`,`To redirect, go to Apps, Google Workspace, Gmail, Routing (not Default routing). Under Email forwarding using recipient address map, map the leaver's address to the replacement. Redirected mail is not delivered to the original account.`],sources:[`g-delete`,`g-redirect`]}]},{heading:`Reclaim the license`,paragraphs:[`Suspending does not save money. Suspended accounts are billed like active ones.`,`On the Annual or Fixed-Term plan, deleting an account does not reduce your license count or your bill. The seat is yours to reassign. On the Flexible plan, charges are prorated to the deletion date.`,`Archiving moves the person to an Archived User license and makes their Workspace license available to reassign within 24 hours.`],sources:[`g-suspend`,`g-delete`,`g-archive`]},{heading:`Timing: what you can still undo`,bullets:[`Suspend: reversible at any time.`,`Delete: restorable for up to 20 days, and only if a matching license is available and the username has not been reused as an alias or group address.`,`Transfer before you delete. If a transfer fails during deletion, Google stops the deletion and leaves the account untouched.`,`A user on a Vault litigation hold cannot be deleted or have data transferred until the hold is lifted, which can take up to 48 hours to take effect.`],sources:[`g-restore`,`g-delete`]}],faq:[{q:`Should I suspend or delete a former employee in Google Workspace?`,a:`Suspend on the last day so access stops and nothing is lost. Once Drive, Calendar and mail are handed over, archive the account if you must keep the data, or delete it if you do not.`},{q:`How long can I restore a deleted Google Workspace user?`,a:`Up to 20 days after deletion, according to Google's admin help. You need an available license, and the username must not have been reused.`},{q:`Does suspending a user sign them out everywhere?`,a:`Suspension resets their sign-in cookies automatically and blocks access to services. Google notes that a cookie reset alone does not sign someone out of apps like Gmail and Google Drive for desktop, so suspend rather than relying on the cookie reset.`},{q:`Does suspending a user stop billing?`,a:`No. Google charges suspended accounts at the same rate as active ones. Archive or delete the account to reuse or drop the seat.`},{q:`What happens to files the person shared with others?`,a:`Drive files they own go with the account when it is deleted unless you transfer them first. Files in shared drives belong to the organization and stay.`}],truehound:{text:`When the Google Workspace connector is switched on, Truehound lists every Workspace account next to the people who have left, flags anyone who left but is still active, and adds the result to your access review with evidence. Today the live product is the GitHub Access Audit.`,afterSwitchOn:!0},sources:[{id:`g-delete`,label:`Google Workspace Admin Help: Delete or remove a user from your organization`,url:`https://knowledge.workspace.google.com/admin/users/delete-or-remove-a-user-from-your-organization`},{id:`g-suspend`,label:`Google Workspace Admin Help: Suspend a user temporarily`,url:`https://knowledge.workspace.google.com/admin/users/suspend-a-user-temporarily`},{id:`g-archive`,label:`Google Workspace Admin Help: Archive former employee accounts`,url:`https://knowledge.workspace.google.com/admin/users/archive-former-employee-accounts`},{id:`g-restore`,label:`Google Workspace Admin Help: Restore a recently deleted user`,url:`https://knowledge.workspace.google.com/admin/users/restore-a-recently-deleted-user`},{id:`g-signout`,label:`Google Workspace Admin Help: Sign a user out of a managed Google Account`,url:`https://knowledge.workspace.google.com/admin/devices/sign-a-user-out-of-a-managed-google-account`},{id:`g-security`,label:`Google Workspace Admin Help: Manage a user's security settings`,url:`https://knowledge.workspace.google.com/admin/security/manage-a-users-security-settings`},{id:`g-drive`,label:`Google Workspace Admin Help: Transfer Drive files to a new owner as an admin`,url:`https://knowledge.workspace.google.com/admin/drive/transfer-drive-files-to-a-new-owner-as-an-admin`},{id:`g-groups`,label:`Google Workspace Admin Help: Remove or ban users from a group`,url:`https://knowledge.workspace.google.com/admin/groups/remove-or-ban-users-from-a-group`},{id:`g-redirect`,label:`Google Workspace Admin Help: Redirect or forward Gmail messages to another user`,url:`https://knowledge.workspace.google.com/admin/gmail/advanced/redirect-or-forward-gmail-messages-to-another-user`},{id:`g-wipe`,label:`Google Workspace Admin Help: Wipe corporate data from a device`,url:`https://knowledge.workspace.google.com/admin/devices/wipe-corporate-data-from-a-device`}]},{slug:`user-access-review-template-soc-2`,title:`User access review template for SOC 2`,description:`What a SOC 2 auditor asks for in a user access review, a column-by-column template, and how to prove revocations and leavers were handled.`,keyword:`user access review template SOC 2`,checked:`2026-10-21`,readMinutes:5,answer:`A SOC 2 access review is a dated list of every account in each in-scope system, with a named reviewer's keep, revoke or modify decision and a reason for each one. Auditors then look for proof that the revokes actually happened, that every leaver was removed, and that privileged accounts were reviewed. Most practitioners expect the review quarterly. Access reviews and terminations together caused more than a quarter of SOC report exceptions in one 2024 benchmark study.`,sections:[{heading:`Why access reviews trip up SOC 2 audits`,paragraphs:[`SOC 2 uses the AICPA Trust Services Criteria. The logical access criteria (CC6.x) cover how you grant access, remove it when people leave, and limit it to what each role needs. A periodic access review is the usual control auditors test against them.`,`It is also where reports go wrong. CBIZ reviewed 193 SOC reports in its 2024 benchmark study. User access reviews caused 15.6% of exceptions and terminations caused 12%.`],sources:[`aicpa-tsc`,`cbiz-benchmark`]},{heading:`What the auditor typically asks for`,bullets:[`A population list for each in-scope system: every account that had access on a stated date, not just the ones in your identity provider.`,`A named reviewer and a sign-off date for each system. Practitioners warn that a bare checkbox is not enough.`,`A decision for every account: keep, revoke or modify, with the reason recorded.`,`Evidence that each revoke was carried out, such as a ticket or a later export showing the account gone.`,`A leaver reconciliation: people who left in the period, matched against the active account lists, with the date their access ended.`,`A separate look at privileged access: admins, owners and anyone who can grant access to others.`,`A steady cadence. If your policy says quarterly, expect to show every quarter in the audit period, not one review run just before the audit.`],sources:[`iden-playbook`,`vanta-community`,`secureframe-uar`,`thoropass-uar`],caution:`Practitioners flag two common gaps: decisions made in chat threads with no record, and leavers missed because they had a direct app login outside single sign-on.`},{heading:`The template, column by column`,paragraphs:[`One sheet per system, one row per account. Fill the header and the first columns from the system itself, the status from your HR list, and the rest during the review.`],bullets:[`Header, once per system: the system reviewed, its owner, the review period, the date and time the user list was pulled (the snapshot every row shares), how it was pulled, the reviewer and the completion date.`,`Account: the username or email as the system shows it, for example dana@example.com.`,`Person: who the account belongs to. Write Service account or Unknown when there is no person, and give shared accounts a named owner.`,`Status: employee, contractor, left (with the date) or service account, from your HR list or identity provider on the snapshot date.`,`Role or permission: what the account can do, as named in the system.`,`Privileged: yes or no. Yes for admins, owners and anyone who can grant access.`,`Last active: the last sign-in if the system reports it, otherwise Not available.`,`Decision: keep, revoke or change.`,`Reason: one line on why. Required for every keep on a privileged account and every change or revoke.`,`Decided by and Decided on: the named reviewer and the date of the decision.`,`Done on: when the change was made in the system.`,`Proof: how you know it held, for example a re-check of the user list on a date, a ticket or a screenshot reference.`],sources:[`secureframe-uar`,`iden-playbook`,`thoropass-uar`]},{heading:`Run the review in five steps`,steps:[{title:`Export every account list on the same date`,body:[`Pull the account list from each in-scope system on one snapshot date. Include apps people reach with a direct login, not only those behind single sign-on.`],sources:[`iden-playbook`,`vanta-community`]},{title:`Match accounts to people and to HR`,body:[`Fill Person and Employment status. Any account belonging to someone who left is a revoke, and it is also a finding for your offboarding control.`],sources:[`iden-playbook`]},{title:`Send each system to its reviewer`,body:[`The reviewer records a decision and a reason for every row and signs off with a date. A review in which nobody lost any access can look like a rubber stamp, so check privileged rows with extra care.`],sources:[`iden-playbook`,`secureframe-uar`]},{title:`Carry out the revokes and prove it`,body:[`Open a ticket per change and attach evidence when it is done. Auditors ask how flagged access was remediated, so the trail matters as much as the decision.`],sources:[`thoropass-uar`,`vanta-community`]},{title:`File the evidence pack`,body:[`Keep the exports, the completed sheet, the sign-offs and the tickets together under the review date. Your auditor will sample from it.`],sources:[`thoropass-uar`,`secureframe-uar`]}]},{heading:`Download the access review template`,paragraphs:[`The free template at /tools/access-review-template has the columns above, as a CSV for your spreadsheet and a PDF to print and sign. It takes no account and no setup.`,`Coming with the access review plans: Truehound fills the account lists from your systems, matches them to leavers, and builds the evidence pack for you. That part is built but not yet switched on in the live product.`]}],faq:[{q:`How often does SOC 2 require a user access review?`,a:`The criteria do not fix a number. Your own policy sets the cadence and the auditor tests against it. Practitioners say most auditors expect quarterly.`},{q:`Who should review access?`,a:`Someone who knows whether the access is still needed, usually the system owner or the person's manager. Record their name and the date they signed off.`},{q:`Is a screenshot of the user list enough?`,a:`Usually not on its own. Auditors want the decision for each account, the reason, and evidence that revokes were carried out.`},{q:`What counts as privileged access?`,a:`Admins, owners and anyone who can change other people's access or production settings. Flag them in their own column and review them with extra care.`},{q:`Does the review cover people who already left?`,a:`Yes. Reconcile your leavers list against every system's accounts. A leaver who still has an active account is one of the most common exceptions.`}],truehound:{text:`The access review template at /tools/access-review-template is available today with no sign-up. Coming with the access review plans: Truehound pulls the account lists, matches them to leavers and builds the evidence pack. The GitHub Access Audit is live now.`,afterSwitchOn:!0},sources:[{id:`aicpa-tsc`,label:`AICPA and CIMA: 2017 Trust Services Criteria (with revised points of focus, 2022)`,url:`https://www.aicpa-cima.com/resources/download/2017-trust-services-criteria-with-revised-points-of-focus-2022`},{id:`cbiz-benchmark`,label:`CBIZ: The evolution of SOC reporting, final insights from the 2024 SOC benchmark study (part three)`,url:`https://www.cbiz.com/insights/article/the-evolution-of-soc-reporting-final-insights-from-the-2024-soc-benchmark-study-part-three`},{id:`iden-playbook`,label:`Iden: Identity evidence playbook for ISO 27001 and SOC 2`,url:`https://www.idenhq.com/identity-evidence-playbook-iso-27001-soc-2`},{id:`secureframe-uar`,label:`Secureframe Help: FAQs, access review and vendor review evidence`,url:`https://support.secureframe.com/en/articles/15887832-faqs-access-review-and-vendor-review-evidence`},{id:`thoropass-uar`,label:`Thoropass: Stop doing user access review the old way`,url:`https://www.thoropass.com/blog/stop-doing-user-access-review-the-old-way`},{id:`vanta-community`,label:`Vanta Community: SOC 2 Type II access reviews, auditor expectations and common gaps`,url:`https://community.vanta.com/x/grc/jpsl640ola9o/soc-2-type-ii-access-reviews-auditor-expectations`}]},{slug:`remove-user-from-github-organization`,title:`How to remove a user from a GitHub organization`,description:`Remove members, outside collaborators and pending invites in settings or by API, then rotate the deploy keys and secrets they could reach.`,keyword:`remove user from GitHub organization`,checked:`2026-10-21`,readMinutes:5,answer:`Go to your organization's People tab, select the person and choose Remove from organization. Outside collaborators are removed separately, from the Outside collaborators list, and pending invitations must be cancelled too. Removing someone does not revoke deploy keys or secrets they could see, so rotate those afterwards. GitHub keeps a removed member's data for three months in case you reinstate them.`,sections:[{heading:`Members, outside collaborators and pending invitations`,paragraphs:[`GitHub tracks three kinds of people, and each one is removed in a different place.`],bullets:[`Members belong to the organization and get access through teams and base permissions.`,`Outside collaborators are not members. They are added to individual repositories. Removing them from the organization's list removes them from every repository.`,`Pending invitations are people who were invited but never accepted. They are not members yet, but an open invite can still be accepted, so cancel it.`],sources:[`gh-remove-member`,`gh-rest-outside`,`gh-rest-members`]},{heading:`Remove a person in organization settings`,steps:[{title:`Remove a member`,body:[`Open your profile menu, go to Organizations, and pick your organization. Open the People tab, tick the members to remove, and from the members selected dropdown choose Remove from organization. Review the list and confirm with Remove members.`],sources:[`gh-remove-member`]},{title:`Remove an outside collaborator from all repositories`,body:[`On the People tab, open Outside collaborators in the sidebar. Tick the people to remove, open the dropdown above the list, and choose to remove them from all repositories. Review and confirm.`],sources:[`gh-remove-outside`]},{title:`Check seats if you pay per license`,body:[`Under volume license billing, GitHub does not lower your paid license count when you remove someone. Downgrade the seat count yourself if you want to pay for fewer.`],sources:[`gh-remove-member`]}]},{heading:`Remove a person with the REST API`,paragraphs:[`Scripts help when you offboard several people at once or across several organizations. The authenticated user must be an organization owner.`],bullets:[`DELETE /orgs/{org}/members/{username} removes a member. It also removes them from all teams, and they lose access to the organization's repositories. A successful call returns 204.`,`DELETE /orgs/{org}/memberships/{username} removes an active member, or cancels the invitation if the person was only invited. The user gets an email either way.`,`DELETE /orgs/{org}/invitations/{invitation_id} cancels one pending invitation.`,`GET /orgs/{org}/outside_collaborators lists outside collaborators. DELETE /orgs/{org}/outside_collaborators/{username} removes one from every repository. It returns 422 if the person is actually a member, so use the members endpoint for them.`,`Membership that comes from an enterprise team is not removed by these calls. Remove the person from that enterprise team as well.`],sources:[`gh-rest-members`,`gh-rest-outside`]},{heading:`What happens to forks, invites and reinstatement`,bullets:[`Removed members lose access to their private forks of your private repositories. Local clones on their laptop stay with them; they just cannot sync.`,`For outside collaborators, GitHub deletes their forks of private repositories when you remove them. Again, local clones remain.`,`Invitations the removed member sent and that were never accepted are cancelled.`,`GitHub saves a removed member's data for three months. Invite them back in that window and you can restore their role, team memberships, repository access, private forks, issue assignments and stars.`],sources:[`gh-remove-member`,`gh-remove-outside`,`gh-reinstate`]},{heading:`Revoke what removal does not touch`,steps:[{title:`Rotate deploy keys`,body:[`A deploy key belongs to a repository, not a person. GitHub says the key stays active after the user who added it is removed. Deploy keys never expire, are usually not protected by a passphrase, and a write key can do what an organization admin can. Delete any key the leaver created or held a copy of, and add a new one.`],sources:[`gh-deploy-keys`]},{title:`Rotate Actions secrets they could read`,body:[`GitHub warns that anyone with write access to a repository has read access to all secrets configured in it. If the leaver had write access, assume they could have seen those values. Rotate the secrets in the repositories they could write to, starting with cloud and payment keys.`],sources:[`gh-secure-use`]},{title:`Revoke SAML SSO credential authorizations`,body:[`If your organization uses SAML single sign-on on GitHub Enterprise Cloud, open People, select the member, and open SAML identity linked. Under Authorized credentials, revoke each personal access token and SSH key.`,`Revoking only removes the SAML authorization. The token or key itself still exists on their account; it simply can no longer reach your organization.`],sources:[`gh-saml`]}],caution:`Removing a person from the organization is not the same as making their old credentials useless. Deploy keys and secrets are shared, so they need rotating even after a clean removal.`},{heading:`Enterprise Managed Users and SCIM`,paragraphs:[`With Enterprise Managed Users, your identity provider owns the account. Usernames, profile data, organization membership and repository access are controlled from the IdP, which provisions accounts with SCIM.`,`So offboard in the IdP, not on GitHub. If you use SCIM, remove the person from the GitHub application in your IdP and from any linked IdP groups. For managed users whose membership comes from IdP groups, remove them from every group linked to a team with access to the organization.`],sources:[`gh-emu`,`gh-remove-member`]}],faq:[{q:`Does removing someone from a GitHub organization delete their account?`,a:`No. It removes their access to your organization. Their personal GitHub account stays. Only Enterprise Managed Users accounts are controlled by your identity provider.`},{q:`Can I undo removing a member?`,a:`Yes, within three months. Invite them back and GitHub can restore their role, teams, repository access and private forks.`},{q:`Do they keep copies of private code?`,a:`Any local clone they made stays on their machine. GitHub removes their access to private forks of your private repositories, and deletes those forks for outside collaborators.`},{q:`Do deploy keys stop working when the person who added them leaves?`,a:`No. Deploy keys belong to the repository, not the person, and they do not expire. Delete and replace them yourself.`},{q:`Why does the outside collaborator API return 422?`,a:`The person is a member, not an outside collaborator. Use DELETE /orgs/{org}/members/{username} instead.`}],truehound:{text:`Truehound's GitHub Access Audit is live today. It finds people who left but still have access, outside collaborators, admins, deploy keys, public repositories and secrets in code, with the fix for each and a report you can hand over. Start with the free scan at /scan, which hides names.`,afterSwitchOn:!1},sources:[{id:`gh-remove-member`,label:`GitHub Docs: Removing a member from your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/removing-a-member-from-your-organization`},{id:`gh-reinstate`,label:`GitHub Docs: Reinstating a former member of your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/reinstating-a-former-member-of-your-organization`},{id:`gh-remove-outside`,label:`GitHub Docs: Removing an outside collaborator from an organization repository`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/removing-an-outside-collaborator-from-an-organization-repository`},{id:`gh-rest-members`,label:`GitHub Docs: REST API endpoints for organization members`,url:`https://docs.github.com/en/rest/orgs/members`},{id:`gh-rest-outside`,label:`GitHub Docs: REST API endpoints for outside collaborators`,url:`https://docs.github.com/en/rest/orgs/outside-collaborators`},{id:`gh-saml`,label:`GitHub Docs: Viewing and managing a member's SAML access to your organization`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/granting-access-to-your-organization-with-saml-single-sign-on/viewing-and-managing-a-members-saml-access-to-your-organization`},{id:`gh-deploy-keys`,label:`GitHub Docs: Managing deploy keys`,url:`https://docs.github.com/en/authentication/connecting-to-github-with-ssh/managing-deploy-keys`},{id:`gh-secure-use`,label:`GitHub Docs: Secure use reference for GitHub Actions`,url:`https://docs.github.com/en/actions/reference/security/secure-use`},{id:`gh-emu`,label:`GitHub Docs: About Enterprise Managed Users`,url:`https://docs.github.com/en/enterprise-cloud@latest/admin/managing-iam/understanding-iam-for-enterprises/about-enterprise-managed-users`}]},{slug:`deactivate-slack-user`,title:`How to deactivate a user in Slack`,description:`Who can deactivate a Slack account on each plan, the exact clicks, what happens to messages, files, sessions and apps, and when SCIM can do it for you.`,keyword:`how to deactivate a user in Slack`,checked:`2026-10-21`,readMinutes:5,answer:`Workspace Owners and Admins deactivate people from Admin, Workspace settings, People: click the three dots next to the person and choose Deactivate account. Deactivation signs them out on every device, removes them from all channels and keeps their messages and files. Slack accounts cannot be permanently deleted, only deactivated. Check the apps they installed afterwards, because some stop working and their API tokens are revoked.`,sections:[{heading:`Who can deactivate an account, by plan`,bullets:[`Pro, Business+ and Slack's entry plan: Workspace Admins can deactivate members and guests. Owners can also deactivate Admins, and the Primary Owner can deactivate Owners. No one can deactivate the Workspace Primary Owner.`,`Enterprise plans (often still called Enterprise Grid): Org Admins and Owners can deactivate members, guests, and Workspace Admins and Owners. Only the Org Primary Owner can deactivate Org Owners and Admins. People with the Security Admin or Users Admin system role can act on anyone except the Org Primary Owner.`],sources:[`s-deactivate`]},{heading:`Deactivate a member step by step`,steps:[{title:`On a single workspace (Pro, Business+ or the entry plan)`,body:[`Click Admin in the sidebar, choose Workspace settings, then People. Click the three dots next to the person and select Deactivate account.`],sources:[`s-deactivate`]},{title:`On an Enterprise org`,body:[`Click your organization name in the sidebar, then Tools and settings, Organization settings, People, Members. Tick the person and click Deactivate above the list.`],sources:[`s-deactivate`]},{title:`Force sessions to end now (Enterprise, by API)`,body:[`Deactivation already signs the person out on all devices. On Enterprise plans you can also call the admin.users.session.reset method with a user token that has the admin.users:write scope. It wipes every valid session for that user on all devices.`],sources:[`s-deactivate`,`s-session-reset`]}]},{heading:`What deactivation does to messages, files and sessions`,bullets:[`Messages and files are not deleted. The person is not notified.`,`They are removed from all channels, signed out of your workspaces on all devices, and cannot sign back in.`,`Profile details such as name and photo stay, so old messages still show who wrote them.`,`Slack accounts cannot be permanently deleted, only deactivated. You can reactivate the account later if you change your mind.`],sources:[`s-deactivate`,`s-scim-api`]},{heading:`Guests: deactivate or let the time limit do it`,paragraphs:[`Guest accounts exist only on paid plans. Multi-Channel Guests see only the channels you pick and are billed like regular members. Single-Channel Guests can reach one channel.`,`Admins deactivate guests the same way as members. You can also set a time limit when you invite a guest: Slack deactivates them on that date and reminds the guest and the admin five days before. To keep a guest but narrow what they see, remove them from specific channels instead.`],sources:[`s-guests`,`s-deactivate`]},{heading:`Bots and apps the person installed`,paragraphs:[`When a member is deactivated, some apps they installed deactivate automatically. Bot users, slash commands and incoming webhooks usually keep working, but apps that need that member's permissions may stop completely. Any API tokens the member granted are revoked.`,`Slack keeps a short list of Slack-built apps running whatever the installer's status. For the rest, open the list of deactivated apps and integrations. Reinstall an app, or click Enable for an integration. Reactivating a bot integration regenerates its token, so update any code that used the old one.`,`If every collaborator on an internal app has been deactivated, an Org Owner or Workspace Owner must add a new collaborator before the app can be turned back on.`],sources:[`s-apps`],caution:`Before deactivating someone who built your integrations, list the apps they installed. A deploy notifier or alert bot can go quiet the moment they are deactivated.`},{heading:`Deactivate with SCIM instead of clicks`,paragraphs:[`If your identity provider manages Slack, deactivate there and let SCIM push the change. Slack's SCIM API is available on Business+ and Enterprise plans. Slack's help center adds that the entry and Pro plans get SCIM provisioning only when a Salesforce org is connected to Slack.`,`A SCIM call needs an OAuth token with the admin scope, and the account that generated the token must stay an Admin or Owner. DELETE /Users/{id} sets the Slack user to deactivated. A PATCH that sets active to false does the same, and setting it back to true reactivates the user.`],sources:[`s-scim-api`,`s-scim-ref`,`s-scim-help`]}],faq:[{q:`Can I delete a Slack user instead of deactivating them?`,a:`No. Slack only deactivates accounts. Their messages and files stay, and you can reactivate the account later.`},{q:`Is the person told they were deactivated?`,a:`No. Slack does not notify people when their account is deactivated. They are signed out on all devices and cannot sign back in.`},{q:`Who can deactivate a Workspace Owner?`,a:`On a single workspace, only the Primary Owner can deactivate Owners, and no one can deactivate the Primary Owner. On Enterprise plans, only the Org Primary Owner can deactivate Org Owners and Admins.`},{q:`Will our Slack bots break when the person who set them up leaves?`,a:`Possibly. Some apps deactivate with the installer and their API tokens are revoked. Bot users, slash commands and incoming webhooks usually survive. Check the deactivated apps list right after offboarding.`},{q:`Which Slack plans support SCIM deprovisioning?`,a:`Business+ and Enterprise. Slack's help center says the entry and Pro plans get SCIM only when a Salesforce org is connected.`}],truehound:{text:`When the Slack connector is switched on, Truehound lists every active Slack account next to the people who have left, flags leavers who are still active, and adds the result to your access review with evidence. Today the live product is the GitHub Access Audit.`,afterSwitchOn:!0},sources:[{id:`s-deactivate`,label:`Slack Help Center: Deactivate a member's account`,url:`https://slack.com/help/articles/204475027-Deactivate-a-members-account`},{id:`s-apps`,label:`Slack Help Center: Manage deactivated members' apps and integrations`,url:`https://slack.com/help/articles/360000446446-Manage-deactivated-members-apps-and-integrations`},{id:`s-guests`,label:`Slack Help Center: Understand guest roles in Slack`,url:`https://slack.com/help/articles/202518103-Understand-guest-roles-in-Slack`},{id:`s-scim-help`,label:`Slack Help Center: Manage members with SCIM provisioning`,url:`https://slack.com/help/articles/212572638-manage-members-with-scim-provisioning`},{id:`s-scim-api`,label:`Slack developer docs: SCIM API`,url:`https://docs.slack.dev/admins/scim-api`},{id:`s-scim-ref`,label:`Slack developer docs: SCIM API reference`,url:`https://docs.slack.dev/reference/scim-api/`},{id:`s-session-reset`,label:`Slack developer docs: admin.users.session.reset method`,url:`https://docs.slack.dev/reference/methods/admin.users.session.reset`}]},{slug:`remove-user-aws-iam-access-keys`,title:`How to remove an IAM user and deactivate their access keys`,description:`Find the user and key last-used dates in the credential report, deactivate keys first, then remove every credential and policy in the order AWS requires.`,keyword:`remove IAM user and deactivate access keys`,checked:`2026-10-21`,readMinutes:5,answer:`Download the IAM credential report to see each user's keys and when they were last used. Deactivate the leaver's access keys first, because that is reversible if something breaks. Then delete the password, keys, certificates, SSH keys, service-specific credentials and MFA, remove policies and group memberships, and only then delete the user. Once deleted, the user and its keys cannot be recovered.`,sections:[{heading:`Find the user and their keys in the credential report`,paragraphs:[`In the IAM console choose Credential report, then Download Report. From the CLI run aws iam generate-credential-report and then aws iam get-credential-report. IAM makes a new report at most once every four hours.`,`The report is a CSV. The columns that matter for offboarding are user, password_last_used, mfa_active, access_key_1_active, access_key_1_last_used_date, and the same pair for access key 2.`,`The report does not show service-specific credentials (such as CodeCommit passwords or Bedrock API keys) or any keys beyond the first two. Use ListServiceSpecificCredentials and ListAccessKeys for the full picture.`],sources:[`aws-credreport`],caution:`Before removing a user, AWS suggests checking their recent service activity. An IAM user named after a person is sometimes what a production job uses.`},{heading:`Deactivate first, because it can be undone`,steps:[{title:`Deactivate the access keys`,body:[`Open the user, go to the Security credentials tab, and in Access keys choose Actions, then Deactivate. From the CLI use aws iam update-access-key with the status set to Inactive.`,`A deactivated key can no longer be used by API calls, and you can activate it again if needed. That makes it a safe first move when you are not sure what uses the key.`],sources:[`aws-keys-admin`]},{title:`Block the user without deleting anything`,body:[`To stop all access while keeping credentials in place, attach a policy that denies every action on every resource. Remove the policy to restore access.`],sources:[`aws-remove`]},{title:`Watch the last-used date`,body:[`Check the Access key last used column, or run aws iam get-access-key-last-used. If nothing breaks after a few days, delete.`],sources:[`aws-keys-admin`]}]},{heading:`Delete the IAM user in the order AWS requires`,paragraphs:[`In the console, deleting a user also removes their group memberships, password, inline policies, attached managed policies (the policies themselves are kept) and MFA device. The console asks you to deactivate active access keys first.`,`With the CLI or API you must remove each attached item yourself before DeleteUser will succeed. AWS documents this order:`],steps:[{title:`Delete the console password`,body:[`aws iam delete-login-profile`],sources:[`aws-remove`]},{title:`Delete the access keys`,body:[`aws iam list-access-keys, then aws iam delete-access-key for each one.`],sources:[`aws-remove`]},{title:`Delete signing certificates and SSH public keys`,body:[`aws iam list-signing-certificates and delete-signing-certificate, then list-ssh-public-keys and delete-ssh-public-key. A deleted credential is gone for good.`],sources:[`aws-remove`]},{title:`Delete service-specific credentials`,body:[`aws iam list-service-specific-credentials, then delete-service-specific-credential. These include Git credentials for CodeCommit.`],sources:[`aws-remove`]},{title:`Deactivate and delete MFA devices`,body:[`aws iam list-mfa-devices, then deactivate-mfa-device. For a virtual device, also run delete-virtual-mfa-device.`],sources:[`aws-remove`]},{title:`Remove policies and group memberships`,body:[`Delete inline policies (list-user-policies, delete-user-policy). Detach managed policies (list-attached-user-policies, detach-user-policy). Remove the user from every group (list-groups-for-user, remove-user-from-group).`],sources:[`aws-remove`]},{title:`Delete the user`,body:[`aws iam delete-user. This cannot be undone.`],sources:[`aws-remove`]}]},{heading:`IAM Identity Center users are different`,paragraphs:[`If people sign in through IAM Identity Center, they are not IAM users, and you offboard them in Identity Center instead. Disabling them is not instant: someone with an open access portal session can keep assuming roles until you remove their assignments, and role sessions can last up to 12 hours.`],steps:[{title:`Deny first`,body:[`Add the user's ID to a deny-all policy, either in the permission set's inline policy or in a service control policy, using the identitystore:UserId condition key.`],sources:[`aws-idc-revoke`,`aws-idc-deny`]},{title:`Remove assignments and disable in your IdP`,body:[`Remove the user from all groups and permission set assignments. If you use an external IdP or Active Directory, disable the user there.`],sources:[`aws-idc-revoke`]},{title:`Delete sessions, then disable`,body:[`In the Identity Center console open the user, go to Active sessions, and delete them. Only then choose Disable user access. If you disable first, you can no longer end the session from the console. Keep the deny policy for at least 12 hours.`],sources:[`aws-idc-revoke`]}]},{heading:`Root and shared credentials`,paragraphs:[`AWS says root credentials should be shared only with people who have a strict business need, root should have MFA, and root should not have access keys. If the leaver knew the root password or held a root MFA device, change the password and replace that MFA device.`,`AWS also recommends a group email address for the root user, so account notices do not go to one person's inbox after they leave.`,`Rotate any long-term access keys the leaver could have copied, such as keys for a shared deploy user. AWS lets a user hold two keys at once so you can switch to a new key before deleting the old one.`],sources:[`aws-root-bp`,`aws-keys`,`aws-credreport`]}],faq:[{q:`Should I deactivate or delete an IAM access key?`,a:`Deactivate first. A deactivated key stops working but can be turned back on. Delete it once you are sure nothing depends on it, because deletion is permanent.`},{q:`Why does aws iam delete-user fail?`,a:`With the CLI or API, the user must have no password, access keys, certificates, SSH keys, service-specific credentials, MFA devices, inline or attached policies, or group memberships left. Remove each one, then retry.`},{q:`Can I restore a deleted IAM user?`,a:`No. AWS states that once an IAM user and its access keys are deleted, they cannot be restored or recovered.`},{q:`Does the credential report show every credential?`,a:`No. It covers passwords, the first two access keys, MFA devices and signing certificates. Service-specific credentials and extra keys need ListServiceSpecificCredentials and ListAccessKeys.`},{q:`Is disabling an IAM Identity Center user immediate?`,a:`Not for open role sessions, which can run up to 12 hours. Add a deny policy, remove assignments, delete active sessions, then disable the user.`}],truehound:{text:`When the AWS IAM connector is switched on, Truehound reads your IAM users and key last-used dates, flags people who left but still hold active keys, and adds the result to your access review with evidence. Today the live product is the GitHub Access Audit.`,afterSwitchOn:!0},sources:[{id:`aws-remove`,label:`AWS IAM User Guide: Remove or deactivate an IAM user`,url:`https://docs.aws.amazon.com/IAM/latest/UserGuide/id_users_remove.html`},{id:`aws-credreport`,label:`AWS IAM User Guide: Generate credential reports for your AWS account`,url:`https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_getting-report.html`},{id:`aws-keys-admin`,label:`AWS IAM User Guide: How an IAM administrator can manage IAM user access keys`,url:`https://docs.aws.amazon.com/IAM/latest/UserGuide/access-keys-admin-managed.html`},{id:`aws-keys`,label:`AWS IAM User Guide: Manage access keys for IAM users`,url:`https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_access-keys.html`},{id:`aws-root-bp`,label:`AWS IAM User Guide: Root user best practices for your AWS account`,url:`https://docs.aws.amazon.com/IAM/latest/UserGuide/root-user-best-practices.html`},{id:`aws-idc-revoke`,label:`AWS IAM Identity Center User Guide: Revoke user access`,url:`https://docs.aws.amazon.com/singlesignon/latest/userguide/revoke-user-permissions.html`},{id:`aws-idc-deny`,label:`AWS IAM Identity Center User Guide: Deny user access with Service Control Policies`,url:`https://docs.aws.amazon.com/singlesignon/latest/userguide/authconcept-revoke-access.html`}]},{slug:`find-former-employees-github-organization`,title:`How to find former employees still in your GitHub organization`,description:`List members, outside collaborators and pending invites, match them to your leaver list using verified emails or SAML identities, then check activity and remove.`,keyword:`find former employees still in GitHub organization`,checked:`2026-10-22`,readMinutes:6,answer:`Export three lists from GitHub: organization members, outside collaborators and pending invitations. Match each GitHub username to a real person using verified domain emails or, if SAML single sign-on is on, the linked SAML identity, and compare that against your HR or identity provider list of leavers. Anyone who left but still appears is a removal. GitHub usernames rarely match real names, so the matching step is where most leavers slip through.`,sections:[{heading:`Why leavers stay in GitHub`,paragraphs:[`A GitHub account belongs to the person, not to your company. Turning off someone's work email or identity provider account does not remove their personal GitHub account from your organization. Only with Enterprise Managed Users does your identity provider own the account and its organization membership, provisioned through SCIM. So the organization keeps a list of people that nobody reconciles.`,`The other reason is naming. The People tab shows usernames such as octocat, not legal names, so a leaver is easy to miss by eye.`],sources:[`gh-remove-member`,`gh-emu`]},{heading:`Export everyone who has access`,steps:[{title:`Export the member list`,body:[`Go to your organization, open the People tab, and use the Export dropdown next to the search bar to download a CSV or JSON file. The report includes each username and display name, whether two-factor authentication is on, and whether the person is an owner or a member.`],sources:[`gh-export-members`]},{title:`List outside collaborators`,body:[`Outside collaborators are not members, so they are not in the member export. On the People tab, open Outside collaborators in the sidebar. With the API, GET /orgs/{org}/outside_collaborators returns them, and filter=2fa_disabled narrows the list to those without two-factor authentication.`],sources:[`gh-rest-outside`,`gh-remove-outside`]},{title:`List pending invitations`,body:[`On the People tab, Invitations shows member invites and Pending collaborators shows outside collaborator invites. An open invite sent to a leaver's address can still be accepted, so it belongs on your list. GET /orgs/{org}/invitations returns pending member invitations and GET /orgs/{org}/failed_invitations shows ones that failed.`],sources:[`gh-cancel-invite`,`gh-cancel-collab-invite`,`gh-rest-members`]},{title:`Or pull all three with the GitHub CLI`,body:[`The gh api command calls any REST endpoint with your login and follows every page with --paginate. For example: gh api --paginate orgs/YOUR-ORG/members --jq '.[].login'. Swap members for outside_collaborators or invitations to get the other two lists. GET /orgs/{org}/members also takes role=admin to list only owners.`],sources:[`gh-cli-api`,`gh-rest-members`]}]},{heading:`Match usernames to real people`,paragraphs:[`Your leaver list has names and work emails. GitHub has usernames. You need a bridge between the two.`],bullets:[`Verified domain emails: if you verify your company domain and your organization has agreed to the GitHub Customer Agreement, owners can see each member's email address on that domain. In GraphQL, the organizationVerifiedDomainEmails field on a user returns their verified addresses that match the organization's verified domains.`,`SAML identities: with SAML single sign-on on GitHub Enterprise Cloud, open People, select a member, and open SAML identity linked to see the identity from your identity provider. To do this in bulk, query the organization's samlIdentityProvider in GraphQL; its externalIdentities connection lists the identities your provider linked. Organization owners can read it, including with a classic token that has the read:org scope.`,`No SSO and no verified domain: match by hand using the display name, profile and commit email, and ask each team lead to confirm the usernames on their team. Write down how each match was made.`],sources:[`gh-verify-domain`,`gh-graphql-users`,`gh-saml`,`gh-graphql-orgs`],caution:`A personal email on a GitHub account does not prove who the person is. When a match is a guess, confirm it with the person's manager before you remove anyone.`},{heading:`Check last activity before you act`,bullets:[`Audit log: organization owners can open Settings, then Logs, then Audit log, and search by actor:USERNAME to see what an account did. The log holds the last 180 days, and the view shows three months unless you add a created: date range. You can export it as CSV or JSON.`,`Dormant users report: on GitHub Enterprise Cloud, the enterprise Compliance page can generate a Dormant Users report. An account counts as dormant after 30 days with no qualifying activity, and that covers outside collaborators too.`,`Read dormancy carefully. GitHub says access with a personal access token, SSH key or GitHub App, and Git operations on private repositories, do not count as activity. A quiet account may still be pulling code.`,`The audit log API is only for organizations on GitHub Enterprise Cloud. On other plans, use the web view and its export.`],sources:[`gh-audit-log`,`gh-dormant`]},{heading:`Remove the leavers and what they could reach`,paragraphs:[`For each confirmed leaver, remove the member from the organization, remove the outside collaborator from all repositories, and cancel any pending invitation. GitHub keeps a removed member's data for three months in case you reinstate them. The step by step is in /guides/remove-user-from-github-organization.`,`Then deal with what removal does not touch: deploy keys, Actions secrets and personal access tokens the person could have used. See /guides/rotate-github-deploy-keys. Record each removal with its date; your auditor will want it, and the checklist at /tools/offboarding-checklist covers the other apps.`],sources:[`gh-remove-member`,`gh-remove-outside`]}],faq:[{q:`Does disabling someone in Okta or Google remove them from GitHub?`,a:`Not by itself. A normal GitHub account belongs to the person, and they stay on the member list until you remove them. With Enterprise Managed Users, your identity provider owns the account and its membership, so offboarding there does carry through.`},{q:`Can I see members' work email addresses?`,a:`Yes, if you verify your company domain and your organization has agreed to the GitHub Customer Agreement. Owners can then see each member's email on that domain.`},{q:`Is a dormant account safe to leave?`,a:`No. GitHub does not count token, SSH key or private repository Git activity toward dormancy, so a dormant account may still be in use. Match it to a person and decide.`},{q:`Are outside collaborators in the member export?`,a:`GitHub's member export page lists member fields only. List outside collaborators separately from the People tab or the API.`},{q:`How far back can I see what a leaver did?`,a:`The organization audit log holds 180 days. Export it if you need a longer record.`}],truehound:{text:`Truehound's GitHub Access Audit is live today. Tell it who left and it finds them if they are still in the organization, alongside outside collaborators, owners and repository admins, team maintainers, deploy keys, webhooks, public repositories, secrets in code and two-factor status. It fixes each finding under your approval policy and gives you a report. Start with the free scan at /scan, which hides names.`,afterSwitchOn:!1},sources:[{id:`gh-export-members`,label:`GitHub Docs: Exporting member information for your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/exporting-member-information-for-your-organization`},{id:`gh-rest-members`,label:`GitHub Docs: REST API endpoints for organization members`,url:`https://docs.github.com/en/rest/orgs/members`},{id:`gh-rest-outside`,label:`GitHub Docs: REST API endpoints for outside collaborators`,url:`https://docs.github.com/en/rest/orgs/outside-collaborators`},{id:`gh-cancel-invite`,label:`GitHub Docs: Canceling or editing an invitation to join your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/canceling-or-editing-an-invitation-to-join-your-organization`},{id:`gh-cancel-collab-invite`,label:`GitHub Docs: Canceling an invitation to become an outside collaborator`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/canceling-an-invitation-to-become-an-outside-collaborator-in-your-organization`},{id:`gh-cli-api`,label:`GitHub CLI manual: gh api`,url:`https://cli.github.com/manual/gh_api`},{id:`gh-verify-domain`,label:`GitHub Docs: Verifying or approving a domain for your organization`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/managing-organization-settings/verifying-or-approving-a-domain-for-your-organization`},{id:`gh-graphql-users`,label:`GitHub Docs: GraphQL reference, users (organizationVerifiedDomainEmails)`,url:`https://docs.github.com/en/enterprise-cloud@latest/graphql/reference/users`},{id:`gh-graphql-orgs`,label:`GitHub Docs: GraphQL reference, organizations (samlIdentityProvider)`,url:`https://docs.github.com/en/enterprise-cloud@latest/graphql/reference/orgs`},{id:`gh-saml`,label:`GitHub Docs: Viewing and managing a member's SAML access to your organization`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/granting-access-to-your-organization-with-saml-single-sign-on/viewing-and-managing-a-members-saml-access-to-your-organization`},{id:`gh-audit-log`,label:`GitHub Docs: Reviewing the audit log for your organization`,url:`https://docs.github.com/en/organizations/keeping-your-organization-secure/managing-security-settings-for-your-organization/reviewing-the-audit-log-for-your-organization`},{id:`gh-dormant`,label:`GitHub Docs: Managing dormant users`,url:`https://docs.github.com/en/enterprise-cloud@latest/admin/managing-accounts-and-repositories/managing-users-in-your-enterprise/managing-dormant-users`},{id:`gh-emu`,label:`GitHub Docs: About Enterprise Managed Users`,url:`https://docs.github.com/en/enterprise-cloud@latest/admin/managing-iam/understanding-iam-for-enterprises/about-enterprise-managed-users`},{id:`gh-remove-member`,label:`GitHub Docs: Removing a member from your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/removing-a-member-from-your-organization`},{id:`gh-remove-outside`,label:`GitHub Docs: Removing an outside collaborator from an organization repository`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/removing-an-outside-collaborator-from-an-organization-repository`}]},{slug:`github-outside-collaborators-find-remove`,title:`How to find and remove GitHub outside collaborators`,description:`What outside collaborators are, how to list them in settings or by API, remove them from one repository or all, convert them to members, and limit who can add them.`,keyword:`GitHub outside collaborators remove`,checked:`2026-10-22`,readMinutes:5,answer:`Outside collaborators are people who are not members of your GitHub organization but have been added to one or more of its repositories. List them under People, then Outside collaborators, or with GET /orgs/{org}/outside_collaborators. Remove them from every repository at once from that list, or from a single repository under Manage access. On GitHub Enterprise Cloud you can also stop repository admins from adding new ones.`,sections:[{heading:`What an outside collaborator is`,paragraphs:[`An outside collaborator is a person who is not a member of your organization but has access to one or more of its repositories, at an access level you choose per repository. They cannot be added to teams, because teams are only for members.`,`Base permissions, the default access every member gets, do not apply to outside collaborators. Their access is exactly the set of repositories they were added to, which is why the list is easy to lose track of.`],sources:[`gh-add-outside`,`gh-base-perms`]},{heading:`Why contractors end up there, and stay`,bullets:[`By default, anyone with admin access to a repository can invite outside collaborators to it. Repository admins add an agency or a freelancer to ship one project, and nobody removes them when it ends.`,`GitHub suggests converting a member to an outside collaborator for people who only need some repositories, such as consultants or temporary staff. They lose membership and teams but keep the repositories they were added to directly or through their former teams.`,`Outside collaborators on private repositories use paid licenses on paid plans, so a forgotten contractor also costs a seat.`,`On the People tab they sit in their own list, and GitHub's member export describes member fields only, so a member review can miss them.`],sources:[`gh-outside-setting`,`gh-convert-to-outside`,`gh-add-outside`,`gh-export-members`]},{heading:`List every outside collaborator`,steps:[{title:`In organization settings`,body:[`Go to your organization, open the People tab, and choose Outside collaborators in the sidebar. Pending collaborators, in the same sidebar, lists invitations that have not been accepted yet.`],sources:[`gh-remove-outside`,`gh-cancel-collab-invite`]},{title:`With the REST API`,body:[`GET /orgs/{org}/outside_collaborators lists them for the whole organization; add filter=2fa_disabled to see only those without two-factor authentication. For one repository, GET /repos/{owner}/{repo}/collaborators?affiliation=outside lists its outside collaborators.`],sources:[`gh-rest-outside`,`gh-rest-collaborators`]},{title:`Check each one against a person and a reason`,body:[`For each collaborator, write down who they are, who at your company sponsors them, which repositories they can reach, and when the work ends. Anyone without a current sponsor is a removal. The template at /tools/access-review-template has columns for this.`]}]},{heading:`Remove from one repository or from all of them`,steps:[{title:`From all repositories`,body:[`On People, then Outside collaborators, select the people, open the dropdown and choose Remove from all repositories, then confirm with Remove outside collaborators. By API, DELETE /orgs/{org}/outside_collaborators/{username} does the same. It returns 422 if the person is a member, not an outside collaborator.`],sources:[`gh-remove-outside`,`gh-rest-outside`]},{title:`From a single repository`,body:[`In the Outside collaborators list, click the gear next to the person, choose Manage, then Manage access next to the repository and Remove access to this repository. From the repository side, Settings, then Collaborators and teams, lists everyone with access and has a Remove button. By API, use DELETE /repos/{owner}/{repo}/collaborators/{username}.`],sources:[`gh-remove-outside`,`gh-repo-access`,`gh-rest-collaborators`]},{title:`Cancel pending invitations`,body:[`On People, open Pending collaborators, find the person and cancel the invitation. An unaccepted invite can still be accepted later.`],sources:[`gh-cancel-collab-invite`]}],caution:`GitHub deletes an outside collaborator's forks of your private repositories when you remove them, but any local clone stays on their machine. Removing them also does not lower your paid license count; downgrade the seats yourself.`},{heading:`Convert a collaborator to a member instead`,paragraphs:[`If the person is joining the company, invite them as a member rather than leaving them as a collaborator. On People, then Outside collaborators, open the menu next to their name and choose Invite to organization, then pick a role and teams. They must accept the email invitation, and on per-seat plans you need an unused license before you can invite them.`,`As a member they pick up your base permissions and team access, which you can review in one place.`],sources:[`gh-convert-to-member`,`gh-base-perms`]},{heading:`Limit who can add outside collaborators`,paragraphs:[`On GitHub Enterprise Cloud, open organization Settings, then Member privileges, and under Repository outside collaborators clear Allow repository administrators to invite outside collaborators to repositories for this organization. After that, only organization owners can add them. If your organization belongs to an enterprise, an enterprise policy may set this for you.`,`While you are on Member privileges, check Base permissions. They set the default repository access for every member, from no permission up, and a repository admin can still grant more on a single repository.`],sources:[`gh-outside-setting`,`gh-base-perms`]}],faq:[{q:`Do outside collaborators count toward my GitHub bill?`,a:`On paid plans, adding an outside collaborator to a private repository uses one of your paid licenses.`},{q:`Why does removing an outside collaborator return 422?`,a:`The person is a member, not an outside collaborator. Remove them with the organization members endpoint instead.`},{q:`Can outside collaborators be added to teams?`,a:`No. Team membership is only for organization members. Collaborators are added to repositories one at a time.`},{q:`Who can add outside collaborators?`,a:`By default, anyone with admin access to a repository. On GitHub Enterprise Cloud, owners can restrict this to organization owners only.`},{q:`Does removing a collaborator delete their copy of the code?`,a:`It deletes their forks of your private repositories on GitHub. Local clones on their own machine are not affected.`}],truehound:{text:`Truehound's GitHub Access Audit is live today. It lists outside collaborators, flags those with admin access, and lets you remove them under your approval policy, alongside leavers, owners, deploy keys and secrets in code. The free scan at /scan shows the counts with names hidden.`,afterSwitchOn:!1},sources:[{id:`gh-add-outside`,label:`GitHub Docs: Adding outside collaborators to repositories in your organization`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/adding-outside-collaborators-to-repositories-in-your-organization`},{id:`gh-outside-setting`,label:`GitHub Docs: Setting permissions for adding outside collaborators`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/managing-organization-settings/setting-permissions-for-adding-outside-collaborators`},{id:`gh-base-perms`,label:`GitHub Docs: Setting base permissions for an organization`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-repository-roles/setting-base-permissions-for-an-organization`},{id:`gh-convert-to-outside`,label:`GitHub Docs: Converting an organization member to an outside collaborator`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/converting-an-organization-member-to-an-outside-collaborator`},{id:`gh-convert-to-member`,label:`GitHub Docs: Converting an outside collaborator to an organization member`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/converting-an-outside-collaborator-to-an-organization-member`},{id:`gh-remove-outside`,label:`GitHub Docs: Removing an outside collaborator from an organization repository`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/removing-an-outside-collaborator-from-an-organization-repository`},{id:`gh-cancel-collab-invite`,label:`GitHub Docs: Canceling an invitation to become an outside collaborator`,url:`https://docs.github.com/en/organizations/managing-user-access-to-your-organizations-repositories/managing-outside-collaborators/canceling-an-invitation-to-become-an-outside-collaborator-in-your-organization`},{id:`gh-rest-outside`,label:`GitHub Docs: REST API endpoints for outside collaborators`,url:`https://docs.github.com/en/rest/orgs/outside-collaborators`},{id:`gh-rest-collaborators`,label:`GitHub Docs: REST API endpoints for repository collaborators`,url:`https://docs.github.com/en/rest/collaborators/collaborators`},{id:`gh-repo-access`,label:`GitHub Docs: Managing teams and people with access to your repository`,url:`https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/managing-repository-settings/managing-teams-and-people-with-access-to-your-repository`},{id:`gh-export-members`,label:`GitHub Docs: Exporting member information for your organization`,url:`https://docs.github.com/en/organizations/managing-membership-in-your-organization/exporting-member-information-for-your-organization`}]},{slug:`rotate-github-deploy-keys`,title:`How to rotate GitHub deploy keys when someone leaves`,description:`Deploy keys outlive the person who added them. List them per repository, replace and delete them, then rotate Actions secrets and revoke tokens a leaver could use.`,keyword:`rotate GitHub deploy keys when someone leaves`,checked:`2026-10-22`,readMinutes:6,answer:`A deploy key belongs to a repository, not a person, so it keeps working after the person who added it leaves. To rotate one, generate a new key pair, add the new public key to the repository, switch the server or service to the new private key, then delete the old key. Deploy keys cannot be edited, only replaced. Do the same for Actions secrets the leaver could read, and revoke their fine-grained personal access tokens' access to your organization.`,sections:[{heading:`Why deploy keys survive offboarding`,bullets:[`A deploy key is an SSH key attached to one repository. The private half lives on a server, a CI system, or someone's laptop.`,`GitHub says the key stays active if the user who created it is removed, and that deploy keys are not linked to organization membership.`,`Deploy keys have no expiry date and are usually not protected by a passphrase.`,`Keys are read-only by default, but a key with write access can do what an organization admin or a personal repository collaborator can do.`],sources:[`gh-deploy-keys`],caution:`If the leaver ever had a copy of a deploy key's private half, removing their GitHub account changes nothing for that key. Treat it as theirs until you replace it.`},{heading:`List the deploy keys in each repository`,steps:[{title:`In repository settings`,body:[`Open the repository, go to Settings, then Deploy keys, to see the keys attached to that repository.`],sources:[`gh-deploy-keys`]},{title:`With the REST API or GitHub CLI`,body:[`GET /repos/{owner}/{repo}/keys lists a repository's deploy keys. There is one list per repository, so loop over your repositories. With the GitHub CLI: gh api --paginate repos/YOUR-ORG/REPO/keys. Note the keys with read_only set to false first; those can push.`],sources:[`gh-rest-deploy-keys`,`gh-cli-api`]},{title:`Decide which keys the leaver could have held`,body:[`Keys the leaver created, keys on servers they could log in to, and keys nobody can explain all go on the rotate list. If you cannot say where a private key lives, rotate it.`]}]},{heading:`Rotate a deploy key without breaking deploys`,steps:[{title:`Generate a new key pair where it will be used`,body:[`Run ssh-keygen on the server or in the service that needs access. Each repository needs its own key; GitHub does not let you reuse a deploy key across repositories.`],sources:[`gh-deploy-keys`]},{title:`Add the new public key`,body:[`In the repository, open Settings, then Deploy keys, then Add deploy key. Paste the public key and only tick Allow write access if the system really pushes. By API, POST /repos/{owner}/{repo}/keys with read_only set to true creates a read-only key.`],sources:[`gh-deploy-keys`,`gh-rest-deploy-keys`]},{title:`Switch the system over and test it`,body:[`Point the server or pipeline at the new private key and run a fetch or a deploy to confirm it works.`]},{title:`Delete the old key`,body:[`Remove the old key in Deploy keys, or call DELETE /repos/{owner}/{repo}/keys/{key_id}. GitHub's API reference says deploy keys are immutable: to change one, remove it and create a new one.`],sources:[`gh-rest-deploy-keys`]}]},{heading:`Rotate the Actions secrets they could read`,paragraphs:[`GitHub warns that anyone with write access to a repository has read access to all secrets configured in it. If the leaver could write to a repository, assume they could see its secrets, and rotate the value at the source first (the cloud key, the API token), then update the secret.`,`Organization secrets are shared with all repositories, private repositories, or a selected list. Check each one's repository access in organization Settings, then Secrets and variables, then Actions; if any of those repositories was writable by the leaver, rotate it. The list endpoints such as GET /orgs/{org}/actions/secrets show names and dates, never values. To store the new value, use the Update button there or gh secret set --org YOUR-ORG NAME.`,`Where a cloud provider supports it, GitHub suggests OpenID Connect so workflows stop storing long-lived cloud credentials as secrets at all.`],sources:[`gh-secure-use`,`gh-use-secrets`,`gh-rest-secrets`]},{heading:`Revoke personal access tokens and SSO authorizations`,bullets:[`Organization owners can see every fine-grained personal access token that can reach the organization under Settings, then Personal access tokens, then Active tokens, filter by owner, and revoke them. The person gets an email.`,`That page covers fine-grained tokens only. Classic tokens keep working against your organization until they expire, unless your token policy restricts classic tokens.`,`In Personal access tokens, then Settings, owners can require approval for fine-grained tokens, set a maximum lifetime, and restrict classic tokens.`,`If you use SAML single sign-on, the member's SAML identity page lists authorized credentials, and you can revoke each token and SSH key there. The full removal steps are in /guides/remove-user-from-github-organization.`],sources:[`gh-pat-review`,`gh-pat-policy`,`gh-saml`]},{heading:`Optional: move people to SSH certificates`,paragraphs:[`On GitHub Enterprise Cloud, an organization can trust an SSH certificate authority and sign short-lived certificates for members and outside collaborators. Certificates from CAs added after 27 March 2024 must have a lifetime under one year, and they expire on their own. Single certificates cannot be revoked; removing the CA invalidates everything it signed. That makes certificates a good fit for people, while machines are better served by GitHub Apps, whose installation tokens expire after one hour.`],sources:[`gh-ssh-ca`,`gh-deploy-keys`]}],faq:[{q:`Do deploy keys expire?`,a:`No. GitHub describes deploy keys as credentials that do not have an expiry date. Replace them yourself.`},{q:`Can I edit a deploy key to make it read-only?`,a:`No. Deploy keys are immutable. Add a new read-only key, switch over, and delete the old one.`},{q:`Does removing a person revoke their personal access tokens?`,a:`Removing them from the organization ends their member access, but owners should still review Active tokens for fine-grained tokens, and SAML authorizations where SSO is on.`},{q:`Which secrets should I rotate first?`,a:`Secrets in repositories the leaver could write to, and organization secrets shared with those repositories. Start with cloud, payment and production database credentials.`},{q:`Is there a replacement for deploy keys?`,a:`GitHub recommends GitHub Apps for stronger security: their installation tokens are scoped to chosen repositories and expire after one hour.`}],truehound:{text:`Truehound's GitHub Access Audit is live today. It finds deploy keys across your repositories, along with webhooks, secrets in code on default branches, leavers, outside collaborators and admins, and gives you a report of what was found and fixed. Try the free scan at /scan, which hides names.`,afterSwitchOn:!1},sources:[{id:`gh-deploy-keys`,label:`GitHub Docs: Managing deploy keys`,url:`https://docs.github.com/en/authentication/connecting-to-github-with-ssh/managing-deploy-keys`},{id:`gh-rest-deploy-keys`,label:`GitHub Docs: REST API endpoints for deploy keys`,url:`https://docs.github.com/en/rest/deploy-keys/deploy-keys`},{id:`gh-cli-api`,label:`GitHub CLI manual: gh api`,url:`https://cli.github.com/manual/gh_api`},{id:`gh-secure-use`,label:`GitHub Docs: Secure use reference for GitHub Actions`,url:`https://docs.github.com/en/actions/reference/security/secure-use`},{id:`gh-use-secrets`,label:`GitHub Docs: Using secrets in GitHub Actions`,url:`https://docs.github.com/en/actions/how-tos/write-workflows/choose-what-workflows-do/use-secrets`},{id:`gh-rest-secrets`,label:`GitHub Docs: REST API endpoints for GitHub Actions secrets`,url:`https://docs.github.com/en/rest/actions/secrets`},{id:`gh-pat-review`,label:`GitHub Docs: Reviewing and revoking personal access tokens in your organization`,url:`https://docs.github.com/en/organizations/managing-programmatic-access-to-your-organization/reviewing-and-revoking-personal-access-tokens-in-your-organization`},{id:`gh-pat-policy`,label:`GitHub Docs: Setting a personal access token policy for your organization`,url:`https://docs.github.com/en/organizations/managing-programmatic-access-to-your-organization/setting-a-personal-access-token-policy-for-your-organization`},{id:`gh-saml`,label:`GitHub Docs: Viewing and managing a member's SAML access to your organization`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/granting-access-to-your-organization-with-saml-single-sign-on/viewing-and-managing-a-members-saml-access-to-your-organization`},{id:`gh-ssh-ca`,label:`GitHub Docs: About SSH certificate authorities`,url:`https://docs.github.com/en/enterprise-cloud@latest/organizations/managing-git-access-to-your-organizations-repositories/about-ssh-certificate-authorities`}]},{slug:`soc-2-terminated-employee-access-removal-timeline`,title:`How fast must you remove a terminated employee's access for SOC 2?`,description:`SOC 2 sets no fixed deadline. Your policy sets it and the auditor tests you against it. Common windows, what evidence gets sampled, and how teams miss it.`,keyword:`how fast must you remove access for terminated employees SOC 2`,checked:`2026-10-22`,readMinutes:5,answer:`SOC 2 does not set a number. The logical access criteria (CC6.x) expect access to be removed when someone is no longer authorized, and your own policy says how fast. The auditor then tests every sampled leaver against the window you wrote down. Common policies say same day, 24 hours, one business day or 48 hours; pick one you can meet every time, because missing your own deadline is the exception.`,sections:[{heading:`SOC 2 sets no fixed deadline`,paragraphs:[`SOC 2 reports are built on the AICPA Trust Services Criteria. The logical access criteria, CC6.x, cover granting access, removing it when people leave, and limiting it to what a role needs. They describe the outcome, not a number of hours.`,`So the deadline is yours. Practitioners put it plainly: set a termination period your organization can achieve, because the auditor tests the control against the requirement you define. Write the window into your logical access policy as well as the control.`],sources:[`aicpa-tsc`,`strikegraph-termination`]},{heading:`Common windows companies choose`,bullets:[`Same day: the strictest choice. Only promise it if your process really runs that fast, every time.`,`24 hours: a widely used example reads that user access is revoked within 24 hours of the employee record being terminated in the HR system.`,`One business day: another common wording is that access no longer required for terminated or transferred users is removed within one business day. Bastion describes the typical window as 24 hours or one business day.`,`48 hours: Strike Graph's default control language says access is revoked within 48 hours of termination or transfer, and tells you to customise it. If you always remove access within 24 hours, write 24.`],sources:[`secboulevard-termination`,`strikegraph-termination`,`bastion-exceptions`],caution:`A shorter window is not better if you miss it. A late removal in the sample is an exception, while a longer window you always meet is not.`},{heading:`What the auditor samples`,steps:[{title:`The population of leavers`,body:[`For a Type 2 report, expect a request for a termination list for the audit period from your HR or payroll system. The auditor picks a sample from it.`],sources:[`strikegraph-termination`,`soc2auditors-checklist`]},{title:`Proof of removal for each sampled leaver`,body:[`For each sampled person, the auditor wants a ticket or checklist showing access was removed within your stated interval. One practitioner checklist expects a revocation log covering every system the person held, with timestamps, not just the identity provider.`],sources:[`strikegraph-termination`,`iden-cc6`]},{title:`Termination date against removal timestamp`,body:[`The test is simple arithmetic: the termination date from HR against the date access ended in each system. A deactivation inside the policy deadline for every sampled leaver is what passes.`],sources:[`soc2auditors-checklist`,`strikegraph-termination`]},{title:`The written procedure`,body:[`Strike Graph also lists your access termination procedure as evidence, including who first notifies IT that access must be removed.`],sources:[`strikegraph-termination`]}]},{heading:`Where teams miss the window`,bullets:[`Terminations caused 12% of control exceptions across the 193 SOC reports in CBIZ's 2024 benchmark study, behind business approvals and reviews (16.5%) and user access reviews (15.6%).`,`Bastion calls deprovisioning the most frequently cited exception, usually because HR tells IT late or the offboarding checklist is incomplete. Its example: someone resigns on Friday and their AWS and GitHub access is removed the next Tuesday.`,`Apps outside single sign-on or SCIM are hard to track, so leavers keep direct logins there.`,`Contractors often are not in the HR system, so no termination event ever fires for them.`,`Missing evidence: the access was removed, but nobody can show when.`],sources:[`cbiz-benchmark`,`bastion-exceptions`,`secboulevard-termination`,`iden-cc6`]},{heading:`Make the window hold`,steps:[{title:`Start the clock from HR`,body:[`Connect your HR system to your identity provider where you can, so the termination date starts deprovisioning. Bastion recommends triggering it on the termination date.`],sources:[`bastion-exceptions`]},{title:`Keep a per-system checklist`,body:[`List every in-scope system, including those people reach with a direct login, and record the removal time for each. The offboarding checklist at /tools/offboarding-checklist builds one for your apps.`],sources:[`bastion-exceptions`,`iden-cc6`]},{title:`Reconcile weekly`,body:[`Bastion suggests checking recent terminations against access each week, so a miss is caught days after it happens rather than in the audit.`],sources:[`bastion-exceptions`]},{title:`Check your readiness`,body:[`The readiness quiz at /tools/access-review-readiness shows where your offboarding and access review evidence is thin. For the quarterly review itself, see /guides/user-access-review-template-soc-2.`]}]}],faq:[{q:`Does SOC 2 require removing access within 24 hours?`,a:`No. The criteria do not name a number. 24 hours is a common policy choice, and the auditor tests you against whatever window your policy states.`},{q:`Is a longer window a red flag?`,a:`Practitioners advise a window you can achieve. A window you always meet is better than a short one you sometimes miss. Agree the wording with your auditor.`},{q:`What counts as the start of the clock?`,a:`Whatever your policy says, most often the termination date or the moment the HR record is terminated. Write it down so the auditor measures from the same point you do.`},{q:`Do contractors count?`,a:`Yes, if they had access to in-scope systems. They are easy to miss because they are often not in the HR system.`},{q:`Is removing someone from the identity provider enough?`,a:`Only for apps that run through it. Auditors look at every in-scope system, and apps with direct logins are a common gap.`}],truehound:{text:`Today you can use two free tools with no sign-up, the offboarding checklist at /tools/offboarding-checklist and the readiness quiz at /tools/access-review-readiness, and the GitHub Access Audit is live. Coming with the access review plans: Truehound starts an SLA clock when someone leaves, checks each connected app, and records the removal time for your evidence pack. That part is built but not switched on in the live product.`,afterSwitchOn:!0},sources:[{id:`aicpa-tsc`,label:`AICPA and CIMA: 2017 Trust Services Criteria (with revised points of focus, 2022)`,url:`https://www.aicpa-cima.com/resources/download/2017-trust-services-criteria-with-revised-points-of-focus-2022`},{id:`strikegraph-termination`,label:`Strike Graph Help: Deep dive, termination of access and access removal procedures`,url:`https://help.strikegraph.com/articles/7207735-deep-dive-termination-of-access-and-access-removal-procedures`},{id:`secboulevard-termination`,label:`Security Boulevard (Trustero): SOC 2 controls, access removal for terminated or transferred users`,url:`https://securityboulevard.com/2022/11/soc-2-controls-access-removal-for-terminated-or-transferred-users-an-updated-guide/`},{id:`bastion-exceptions`,label:`Bastion: Most common exceptions found during a SOC 2 audit`,url:`https://bastion.tech/blog/most-common-soc2-audit-exceptions`},{id:`cbiz-benchmark`,label:`CBIZ: The evolution of SOC reporting, final insights from the 2024 SOC benchmark study (part three)`,url:`https://www.cbiz.com/insights/article/the-evolution-of-soc-reporting-final-insights-from-the-2024-soc-benchmark-study-part-three`},{id:`soc2auditors-checklist`,label:`SOC2Auditors.org: SOC 2 audit checklist`,url:`https://soc2auditors.org/insights/soc-2-audit-checklist`},{id:`iden-cc6`,label:`Iden: SOC 2 CC6 evidence checklist`,url:`https://www.idenhq.com/checklists/soc-2-cc6/md`}]},{slug:`remove-user-microsoft-365-entra-id`,title:`How to remove a former employee from Microsoft 365 and Entra ID`,description:`Reset the password, revoke sessions, block sign-in, wipe devices, keep their mail and OneDrive, remove licenses, then delete the user with 30 days to restore.`,keyword:`remove former employee Microsoft 365 Entra ID`,checked:`2026-10-22`,readMinutes:6,answer:`Reset the person's password and sign them out of all sessions first, because blocking sign-in alone can take up to 24 hours to take effect. Then block sign-in, wipe or block their devices, convert the mailbox to a shared mailbox or forward it, and give their manager access to their OneDrive. Remove licenses once the data is safe. Deleting the user keeps them restorable for 30 days, after which their OneDrive and mail are gone.`,sections:[{heading:`Cut access first`,steps:[{title:`Reset the password and sign out of all sessions`,body:[`In the Microsoft 365 admin center, go to Users, then Active users, select the person and choose Reset password. Then, on the Account tab, choose Sign out of all sessions.`,`Microsoft says the user is asked to sign in again within an hour, or when they leave the page they are on, because an access token lasts an hour. Outlook on the web may not sign them out until they switch apps or refresh.`],sources:[`ms-step1`]},{title:`Block sign-in`,body:[`In Active users, select the person, choose Block sign-in, tick Block this user from signing in and save. In the Microsoft Entra admin center the same switch is Account enabled, under Entra ID, then Users, then the user's Account status.`,`Microsoft warns that blocking can take up to 24 hours to take effect, which is why the password reset comes first.`],sources:[`ms-step1`,`entra-revoke`]},{title:`Revoke refresh tokens with PowerShell`,body:[`For a scripted or bulk offboarding, use Microsoft Graph PowerShell. Update-MgUser -UserId ID -AccountEnabled:$false disables the account, and Revoke-MgUserSignInSession -UserId ID invalidates every refresh token issued to apps for that user, and their browser session cookies, by resetting signInSessionsValidFromDateTime to now.`,`A user principal name such as dana@example.com works as the user ID.`],sources:[`entra-revoke`,`ms-revoke-cmdlet`]},{title:`Block mail apps in Exchange Online`,body:[`In the Exchange admin center, open Recipients, then Mailboxes, select the mailbox, choose Manage email apps settings and turn off every protocol: Outlook desktop, Exchange web services, mobile, IMAP, POP3 and Outlook on the web.`],sources:[`ms-step1`]}],caution:`Revoking sessions stops new tokens from Entra ID. Apps that issue their own session token keep it until it expires or the app ends it, so deprovision the person in those apps too.`},{heading:`Wipe and block their devices`,bullets:[`Phone with company mail: in the Exchange admin center, open the mailbox, choose Manage mobile devices, select the device, choose an option such as Account Only Remote Wipe Device, then Block access.`,`Devices managed in Intune: in the Intune admin center, go to Devices, then All devices, open the device and choose Remove data, then Wipe. This resets it to factory settings and cannot be undone. On unmanaged devices you can wipe only the company data in managed apps.`,`Microsoft notes that an Intune wipe needs the device to be connected to the internet. An offline device still has its local data.`,`Disable the person's registered devices in Entra ID too, with Get-MgUserRegisteredDevice and Update-MgDevice -AccountEnabled:$false.`],sources:[`ms-step3`,`intune-wipe`,`entra-revoke`]},{heading:`Keep their mail and OneDrive`,steps:[{title:`Convert the mailbox to a shared mailbox, or forward it`,body:[`A shared mailbox keeps all existing mail and calendar items for several people to read, and needs no license while it stays under 50 GB. Forwarding only sends new mail on.`,`Do not delete the account if you forward mail or keep a shared mailbox. The account anchors both.`],sources:[`ms-step4`]},{title:`Give the manager their OneDrive`,body:[`In Active users, open the person, choose OneDrive, then Create link to files under Get access to files to copy or move what you need. To hand the whole OneDrive to someone else, a SharePoint admin adds them as a site collection administrator of that OneDrive under User profiles.`,`After you delete the account, you have 30 days by default to reach their OneDrive. You can change that with the OneDrive retention setting for deleted users.`],sources:[`ms-step5`]}]},{heading:`Remove licenses and roles`,paragraphs:[`In Active users, open the person, go to Licenses and apps, clear the licenses and save. Remove any holds first. Then lower the license count under Billing, Your products, if you will not reassign the seat.`,`When a license is removed, the person's mail, contacts and calendar are kept for 30 days and then permanently deleted. If you need them for legal reasons, put a hold on the mailbox before deleting the user.`,`If the person held admin roles, take them off too, and check apps and groups they owned before you delete the account.`],sources:[`ms-step6`]},{heading:`Delete the user, and the 30 day window`,paragraphs:[`In the Microsoft Entra admin center, go to Entra ID, then Users, select the person and choose Delete user. They move to Deleted users, where you can restore them for 30 days. Their licenses become available straight away.`,`If your accounts sync from on-premises Active Directory, delete the user there instead; Microsoft 365 cannot delete or restore synced accounts. In a hybrid setup, Microsoft recommends disabling the account in Active Directory and resetting its password twice.`],sources:[`entra-delete`,`ms-overview`,`entra-revoke`]}],faq:[{q:`Does blocking sign-in end their current sessions?`,a:`Not right away. Blocking can take up to 24 hours. Reset the password and choose Sign out of all sessions, or run Revoke-MgUserSignInSession, to force a new sign-in.`},{q:`Do I need to keep paying for a license to keep their mail?`,a:`Not if you convert the mailbox to a shared mailbox under 50 GB. Larger shared mailboxes need a license.`},{q:`How long can I restore a deleted user?`,a:`30 days from the Deleted users page. After that their OneDrive and mail content is gone unless you changed retention or placed a hold.`},{q:`Does removing them in Entra ID remove them from GitHub or Slack?`,a:`Only for apps provisioned from Entra ID. Apps with their own logins or their own tokens need their own offboarding; see /guides/remove-user-from-github-organization.`},{q:`What about apps that use their own session?`,a:`Entra ID cannot revoke a session token another app issued. Deprovision the user in that app, or use automatic provisioning so it happens for you.`}],truehound:{text:`Coming with the Microsoft connector: Entra ID as the source of who left, so suspending someone there starts a check of every connected app. That is built but not switched on in the live product. Live today is the GitHub Access Audit, with the free scan at /scan. Among the free tools is the offboarding checklist at /tools/offboarding-checklist.`,afterSwitchOn:!0},sources:[{id:`ms-overview`,label:`Microsoft Learn: Remove a former employee, overview`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee`},{id:`ms-step1`,label:`Microsoft Learn: Step 1, prevent user sign-in and block access to Microsoft 365`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee-step-1`},{id:`ms-step3`,label:`Microsoft Learn: Step 3, wipe and block a former employee's mobile device`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee-step-3`},{id:`ms-step4`,label:`Microsoft Learn: Step 4, forward email or convert to a shared mailbox`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee-step-4`},{id:`ms-step5`,label:`Microsoft Learn: Step 5, give another employee access to OneDrive and Outlook data`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee-step-5`},{id:`ms-step6`,label:`Microsoft Learn: Step 6, remove and delete a Microsoft 365 license from a former employee`,url:`https://learn.microsoft.com/en-us/microsoft-365/admin/add-users/remove-former-employee-step-6`},{id:`entra-revoke`,label:`Microsoft Learn: Revoke user access in an emergency in Microsoft Entra ID`,url:`https://learn.microsoft.com/en-us/entra/identity/users/users-revoke-access`},{id:`ms-revoke-cmdlet`,label:`Microsoft Learn: Revoke-MgUserSignInSession`,url:`https://learn.microsoft.com/en-us/powershell/module/microsoft.graph.users.actions/revoke-mgusersigninsession`},{id:`entra-delete`,label:`Microsoft Learn: How to create, invite, and delete users in Microsoft Entra ID`,url:`https://learn.microsoft.com/en-us/entra/fundamentals/how-to-create-delete-users`},{id:`intune-wipe`,label:`Microsoft Learn: Wipe devices with Microsoft Intune`,url:`https://learn.microsoft.com/en-us/intune/device-management/actions/wipe`}]},{slug:`okta-deactivate-user-what-it-removes`,title:`Okta deactivate user: what it removes and what it leaves behind`,description:`Deactivating an Okta user ends sessions and app assignments, but apps only lose the account where deprovisioning is set up. Suspend, deactivate and delete compared.`,keyword:`Okta deactivate user`,checked:`2026-10-22`,readMinutes:5,answer:`Deactivating a user in Okta stops all their active Okta sessions, revokes their app assignments and admin roles, and blocks new sign-ins. The account in each app is only deactivated where that app has provisioning with Deactivate Users turned on. Apps people sign in to directly, local passwords, and keys or tokens created inside other apps are not touched, so they need their own offboarding.`,sections:[{heading:`What deactivation does in Okta`,bullets:[`The user can no longer create sessions, and all their active sessions in Okta are stopped.`,`Their app assignments are revoked, so they can no longer reach their assigned apps through Okta.`,`Their admin roles are revoked and they are unassigned from the Okta Admin app.`,`Okta API tokens the user created are deprovisioned at the same time, because those tokens act with the creating admin's privileges. Integrations that used them will stop working.`,`Deactivation runs as a background task; large batches can take a while. The user's status becomes DEPROVISIONED when it finishes.`],sources:[`okta-deactivate`,`okta-api-token`,`okta-lifecycle-api`]},{heading:`When apps actually lose the account`,paragraphs:[`Removing the assignment in Okta stops single sign-on into the app. Whether the account inside the app is also deactivated depends on provisioning. Okta deprovisions the user from assigned apps only where deprovisioning is enabled for that app, and skips inactive apps.`,`For apps with provisioning, open the app under Applications, go to the Provisioning tab, choose To App, and enable Deactivate Users. Okta then deactivates the person's account in that app when they are unassigned or deactivated in Okta. For apps that need manual deprovisioning, Okta puts a notice on the admin dashboard instead.`],sources:[`okta-deactivate`,`okta-auto-deactivate`,`okta-lcm`,`okta-not-retroactive`],caution:`Turning on Deactivate Users is not retroactive. It only applies to deactivations and unassignments after you enable it, so people deactivated earlier may still have live accounts in that app.`},{heading:`What deactivation does not touch`,bullets:[`Apps people sign in to with a local password rather than through Okta. Deactivating the Okta user does nothing there.`,`Apps with only single sign-on, no provisioning: the person loses the Okta route in, but the account in the app stays until someone removes it.`,`Keys and tokens created inside other systems. A GitHub deploy key, for example, belongs to the repository and stays active after the person who added it is removed. See /guides/rotate-github-deploy-keys.`,`Group memberships in Okta. Deactivated users are not removed from groups; that only happens on deletion.`,`Authentication factors and the user's data in Okta, which are removed only when the user is deleted.`],sources:[`okta-deactivate`,`okta-lcm`,`gh-deploy-keys`]},{heading:`Suspend, deactivate or delete`,bullets:[`Suspend: for a leave of absence or a paused contractor. Suspended users cannot sign in to Okta, and their app and group memberships are kept and reinstated when you unsuspend them. Only active users can be suspended.`,`Deactivate: for someone who has left. Sessions end and app assignments and admin roles are revoked. Okta's API reference calls deactivation a destructive operation, so be sure before you run it.`,`Delete: permanent, and you cannot undo it. A user must be deactivated before they can be deleted. Deletion removes factors, group memberships, linked objects and the user's data in Universal Directory, frees the username for reuse, and Okta starts permanent deletion of customer data within 30 days.`],sources:[`okta-suspend`,`okta-lifecycle-api`,`okta-deactivate`]},{heading:`Deactivate a user in the Admin Console`,steps:[{title:`Check privileged access and service tokens first`,body:[`If the user is managed with Okta Privileged Access, end that first. If they created API tokens your integrations rely on, create replacements from a service account before you deactivate, since Okta recommends service accounts for API tokens.`],sources:[`okta-deactivate`,`okta-api-token`]},{title:`Deactivate`,body:[`In the Admin Console, go to Directory, then People, then More Actions, then Deactivate. Select the users, choose Deactivate Selected, and confirm.`],sources:[`okta-deactivate`]},{title:`Clean up the apps Okta did not reach`,body:[`List the apps the person used that have no provisioning or use direct logins, and remove the account in each. The checklist at /tools/offboarding-checklist builds that list for your apps.`]}]}],faq:[{q:`Does deactivating a user in Okta remove them from all apps?`,a:`It removes their Okta assignments and access through Okta. The account inside each app is only deactivated where provisioning with Deactivate Users is set up.`},{q:`Can I reactivate a deactivated user?`,a:`Yes. Reactivating restores the account, but you may need to reassign some apps. Group rules can do that for you.`},{q:`What happens to Okta API tokens the person created?`,a:`They are deprovisioned when the user is deactivated. Create integration tokens from a service account so this does not break anything.`},{q:`Should I suspend or deactivate a leaver?`,a:`Deactivate. Suspension keeps app and group memberships so the person can come back, which is meant for leave or temporary pauses.`},{q:`Why is a deactivated user still in an app?`,a:`The app has no provisioning, Deactivate Users is off, the app is inactive in Okta, or the person was deactivated before you enabled the setting.`}],truehound:{text:`Coming with the Okta connector: Truehound reads who was deactivated in Okta and checks each connected app for an account that is still live. That is built but not switched on in the live product. Live today is the GitHub Access Audit, which finds leavers you name, outside collaborators and deploy keys; start with the free scan at /scan.`,afterSwitchOn:!0},sources:[{id:`okta-deactivate`,label:`Okta Help: Deactivate and delete user accounts`,url:`https://help.okta.com/en-us/content/topics/users-groups-profiles/usgp-deactivate-user-account.htm`},{id:`okta-suspend`,label:`Okta Help: Suspend a user`,url:`https://help.okta.com/en-us/content/topics/users-groups-profiles/usgp-suspend.htm`},{id:`okta-auto-deactivate`,label:`Okta Help: Automatically deactivate app users`,url:`https://help.okta.com/en-us/Content/Topics/provisioning/lcm/lcm-automatic-deactivate.htm`},{id:`okta-lcm`,label:`Okta Help: Lifecycle of a provisioned user`,url:`https://help.okta.com/oie/en-us/content/topics/provisioning/lcm/lcm-provisioning-workflow.htm`},{id:`okta-not-retroactive`,label:`Okta Support: Provisioning Deactivate Users only applies to new deactivated or unassigned users`,url:`https://support.okta.com/help/s/article/provisioning-deactivate-users-button-deactivate-just-new-deactivated-unassigned-users`},{id:`okta-api-token`,label:`Okta Developer: Create an API token`,url:`https://developer.okta.com/docs/guides/create-an-api-token/main/`},{id:`okta-lifecycle-api`,label:`Okta Developer: Java SDK reference, UserLifecycleApi`,url:`https://developer.okta.com/okta-sdk-java/apidocs/com/okta/sdk/resource/api/UserLifecycleApi.html`},{id:`gh-deploy-keys`,label:`GitHub Docs: Managing deploy keys`,url:`https://docs.github.com/en/authentication/connecting-to-github-with-ssh/managing-deploy-keys`}]},{slug:`lean-access-management-google-workspace-entra`,title:`Lean access management: keep Google or Microsoft as your identity core`,description:`A playbook for 10 to 200 person companies: Google Workspace or Entra as the identity core, no enterprise IdP, and proof every removal held.`,keyword:`lean access management without Okta`,checked:`2026-10-22`,readMinutes:9,answer:`You do not need an enterprise identity provider to control access well at 10 to 200 people. Use the Google Workspace or Microsoft Entra account you already pay for as the one list of who works here, sign in to apps through it where your plan allows, and keep a short list of the apps that live outside it. The part most teams skip is proof: after you remove someone, read each app's user list again and keep the dated result.`,sections:[{heading:`Why the identity core you already have is enough`,paragraphs:[`Every company on Google Workspace or Microsoft 365 already has a directory: one account per person, with a clear state of active or suspended. That is the record an auditor asks you to reconcile against, and it costs nothing extra.`,`Both can act as the sign-in for other apps. Google Workspace lets an admin set up a custom SAML app, and Entra lets you add enterprise applications for single sign-on and, where the app supports it, automatic provisioning.`,`What a dedicated identity platform adds is mostly breadth and automation for large estates: more prebuilt connectors, lifecycle workflows and policy engines. Okta's Essentials suite, which includes lifecycle management, is listed at $17 per user a month, billed annually, with a $1,500 annual minimum. At 100 people that is $20,400 a year before any app upgrades.`],sources:[`google-saml`,`entra-apps`,`entra-provisioning`,`okta-pricing`]},{heading:`The SSO tax, and how to plan around it`,paragraphs:[`Many SaaS vendors put single sign-on, and often SCIM provisioning, only on their higher plans. The public list at sso.tax tracks this: for example, it shows Figma at $12 per user a month on the base plan and $45 on the plan with SSO.`,`A lean team does not need to pay that upgrade for every app. Pay for SSO where the app holds sensitive data or many people use it. For the rest, accept that the app keeps its own login, list it, and make sure its user list is checked when someone leaves and at every access review.`],sources:[`sso-tax`],caution:`An app outside single sign-on keeps working after you suspend someone in Google or Microsoft. Suspending the identity is necessary, not sufficient.`},{heading:`The playbook, step by step`,steps:[{title:`Make the directory the source of truth`,body:[`Every person who works for you, including contractors with a work account, is in Google Workspace or Entra. Leavers are suspended there first, the same day, and signed out of active sessions: in Google, suspend the user and sign them out; in Entra, block sign-in and revoke sessions.`],sources:[`google-suspend`,`google-signout`,`entra-revoke`]},{title:`Route sign-in through it where it pays`,body:[`Connect your highest-risk apps (code, cloud, finance, customer data) to Google or Entra for single sign-on. Where the app supports SCIM on your plan, turn on provisioning so a suspension also removes the account.`],sources:[`google-saml`,`entra-provisioning`]},{title:`Control what apps can read from Google`,body:[`In the Google Admin console, API controls let you mark third-party apps as trusted, limited or blocked, and review requests for blocked apps. This keeps apps that sign in with Google from quietly reading Drive or Gmail.`],sources:[`google-api-controls`]},{title:`Keep a short list of everything outside`,body:[`For each app that keeps its own login, write down the owner, the admin page, and how you remove someone. GitHub outside collaborators, deploy keys, cloud access keys and shared passwords belong on this list too, because they never pass through your directory.`,`The offboarding checklist generator at /tools/offboarding-checklist (a free tool) builds this list per app, with each vendor's own instructions.`]},{title:`Remove, then read again`,body:[`When someone leaves, remove them in each app on the list, then pull the app's user list again and confirm they are gone. Record the date. A removal nobody checked is the gap auditors find: terminated users who kept access account for about 12% of SOC exceptions in one benchmark of 193 reports.`],sources:[`cbiz`]},{title:`Review every quarter, with evidence`,body:[`Once a quarter, pull each in-scope system's user list, reconcile it against the directory, decide keep, revoke or change for every account, and sign it off. The free template at /tools/access-review-template has the columns auditors commonly ask for.`],sources:[`cbiz`]}]},{heading:`When an enterprise identity platform is the right call`,bullets:[`You have a dedicated IT or identity team and hundreds of apps to provision automatically.`,`You need advanced policies: device trust, adaptive MFA, complex group rules across many directories.`,`Most of your apps already require an enterprise plan for other reasons, so the SSO upgrades are paid anyway.`],paragraphs:[`If that is you, a platform like Okta earns its price. If it is not, the playbook above covers the same ground for a fraction of it.`]}],faq:[{q:`Can Google Workspace replace Okta for a small company?`,a:`For many small companies, yes: Google Workspace can be the directory and the sign-in for apps through custom SAML apps. You give up some automation and policy depth that a dedicated platform adds.`},{q:`What is the SSO tax?`,a:`The extra price SaaS vendors charge for single sign-on, usually by putting it on a higher plan. sso.tax keeps a public list with base and SSO prices.`},{q:`Does suspending someone in Google remove them from every app?`,a:`No. It stops sign-in through Google. Apps with their own passwords, personal access tokens, deploy keys and cloud access keys keep working until you remove them in each app.`},{q:`How do I prove a removal happened?`,a:`Read the app's user list again after removing the person and keep the dated result with your access review evidence. A ticket that says someone was asked is weaker evidence.`}],truehound:{text:`Truehound is built for exactly this playbook. Live today: the GitHub Access Audit finds people who left but are still in your org, outside collaborators, deploy keys and secrets in code, with fixes under your approval policy; try the free scan at /scan. Coming next: Google Workspace or Entra as the source of who left, removal in each connected app followed by a re-read that proves it held, and a quarterly review that ends in an evidence pack.`,afterSwitchOn:!0},sources:[{id:`google-saml`,label:`Google Workspace Admin Help: Set up your own custom SAML app`,url:`https://knowledge.workspace.google.com/admin/apps/set-up-your-own-custom-saml-app`},{id:`google-api-controls`,label:`Google Workspace Help: Control which third-party and internal apps access Google Workspace data`,url:`https://knowledge.workspace.google.com/admin/apps/control-which-third-party-and-internal-apps-access-google-workspace-data`},{id:`google-suspend`,label:`Google Workspace Admin Help: Suspend a user temporarily`,url:`https://knowledge.workspace.google.com/admin/users/suspend-a-user-temporarily`},{id:`google-signout`,label:`Google Workspace Admin Help: Sign a user out of a managed Google Account`,url:`https://knowledge.workspace.google.com/admin/devices/sign-a-user-out-of-a-managed-google-account`},{id:`entra-apps`,label:`Microsoft Learn: Add an enterprise application`,url:`https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/add-application-portal`},{id:`entra-provisioning`,label:`Microsoft Learn: What is app provisioning in Microsoft Entra ID?`,url:`https://learn.microsoft.com/en-us/entra/identity/app-provisioning/user-provisioning`},{id:`entra-revoke`,label:`Microsoft Learn: Revoke user access in Microsoft Entra ID`,url:`https://learn.microsoft.com/en-us/entra/identity/users/users-revoke-access`},{id:`okta-pricing`,label:`Okta: Workforce Identity pricing`,url:`https://www.okta.com/pricing/`},{id:`sso-tax`,label:`sso.tax: The SSO Wall of Shame`,url:`https://sso.tax/`},{id:`cbiz`,label:`CBIZ: 2024 SOC benchmark study, part three`,url:`https://www.cbiz.com/insights/article/the-evolution-of-soc-reporting-final-insights-from-the-2024-soc-benchmark-study-part-three`}]}];function v(e){return _.find(t=>t.slug===e)}function y(e){return e.toLowerCase().replace(/[^a-z0-9]+/g,`-`).replace(/^-|-$/g,``)}var b=a(),x=o.brand.product,S=`max-w-[26ch] text-balance text-4xl font-medium leading-[1.08] tracking-[-0.025em] text-mkt-ink sm:text-5xl`